import AppKit

/// The matryoshka logo for the menu bar (the color one is drawn live, see Matryoshka.swift). Generated by scripts/make-icon.sh from the SVGs in design/ - do not edit by hand.
enum Icon {
    // One color, for the menu bar.
    private static let closedSVG = """
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
      <path fill-rule="evenodd" d="M12 2C14.6 2 16.3 4 16.3 6.4C16.3 8 16.1 9.4 15.7 10.4C17.4 11.4 18.5 13.1 18.66 14.6L5.34 14.6C5.5 13.1 6.6 11.4 8.3 10.4C7.9 9.4 7.7 8 7.7 6.4C7.7 4 9.4 2 12 2ZM12 4.1A2.4 2.4 0 1 0 12 8.9A2.4 2.4 0 1 0 12 4.1Z"/>
      <path d="M5.3 15.9L18.7 15.9C18.9 17.9 18.3 20.5 17.2 22L6.8 22C5.7 20.5 5.1 17.9 5.3 15.9Z"/>
    </svg>
    """
    private static let openSVG = """
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
      <g transform="translate(11.8 12.4) rotate(24 5.2 0) scale(0.78) translate(-12 -14.6)"><path fill-rule="evenodd" d="M12 2C14.6 2 16.3 4 16.3 6.4C16.3 8 16.1 9.4 15.7 10.4C17.4 11.4 18.5 13.1 18.66 14.6L5.34 14.6C5.5 13.1 6.6 11.4 8.3 10.4C7.9 9.4 7.7 8 7.7 6.4C7.7 4 9.4 2 12 2ZM12 4.1A2.4 2.4 0 1 0 12 8.9A2.4 2.4 0 1 0 12 4.1Z"/></g>
      <g transform="translate(11 16.2) scale(0.4) translate(-12 -14.6)"><path d="M12 2C14.6 2 16.3 4 16.3 6.4C16.3 8 16.1 9.4 15.7 10.4C17.4 11.4 18.5 13.1 18.66 14.6L5.34 14.6C5.5 13.1 6.6 11.4 8.3 10.4C7.9 9.4 7.7 8 7.7 6.4C7.7 4 9.4 2 12 2Z"/></g>
      <g transform="translate(12 22) scale(0.8) translate(-12 -22)"><path d="M5.3 15.9L18.7 15.9C18.9 17.9 18.3 20.5 17.2 22L6.8 22C5.7 20.5 5.1 17.9 5.3 15.9Z"/></g>
    </svg>
    """

    private static func load(_ svg: String, size: CGFloat) -> NSImage {
        let image = NSImage(data: Data(svg.utf8)) ?? NSImage()
        image.size = NSSize(width: size, height: size)
        return image
    }

    /// Menu bar icon: open while leftover processes exist, closed otherwise.
    /// A template image, so the system colors it to match the menu bar.
    static func menuBar(open: Bool) -> NSImage {
        let image = load(open ? openSVG : closedSVG, size: 18)
        image.isTemplate = true
        return image
    }

    static let menuBarClosed = menuBar(open: false)
    static let menuBarOpen = menuBar(open: true)
}
